  "question": "1972年联合国教科文组织在《学会生存》中首次提出教育先行的理念，教育先行亦称教育超前，就是要求教育面向未来，使教育在适应现存生产力和政治经济发展的基础上，适当超前于社会生产力和政治经济发展水平，关于教育先行，以下说法不正确的是（　　）",
