  "category": "德育原则",
  "difficulty": 3,
  "question": "有个班上，有一伙“小捣蛋”爱玩篮球，为了玩球和看球赛，常常影响学习，有时还迟到、旷课，甚至几次抢别班的篮球玩，并引起纠纷，告到班主任那里。班主任把他们叫到办公室，并没有直接采取严厉的训斥，而是向他们说明事情的利弊，语重心长地对他们进行教育，在批评抢球的同时，这位老师还客观地肯定了他们的篮球水平，并很快组织他们成立了一个球队，选了队长，定了队规：一、服从命令听指挥；二、坚持练习守纪律；三、不抢外班的球;四、不做有损球队名誉的事。此后他们每天坚持训练，在活动中练出纪律和自我控制能力。在案例中教师遵循或违背的德育原则有（　　）",
